const saida = $input.first().json.output || {};
const filmes = Array.isArray(saida.movies) ? saida.movies : [];
if (!filmes.length) throw new Error('O agente nao devolveu filmes.');
return filmes.map(function (f, i) {
  return { json: {
    rank: i,
    title: String(f.title || ''),
    originalTitle: String(f.originalTitle || f.title || ''),
    year: Number(f.year) || null,
    reason: String(f.reason || ''),
  } };
});

// O no HTTP devolve um item por item de entrada, na mesma ordem, e
// continueRegularOutput preserva essa ordem tambem em falha. E o que permite
// reassociar cada resposta ao pedido que a gerou.
const pedidos = $('Enfileirar titulos').all();
const respostas = $input.all();

function normalizar(s) {
  return String(s == null ? '' : s)
    .normalize('NFD').replace(/[̀-ͯ]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
}

// Medido na execucao 1660 (01/09/2026). Para 'Cure' (1997) o TMDB devolveu
// tres candidatos: 'The Cure' (1995), 'Say It, Fight It, Cure It' (1997, UM
// voto, documentario) e o do Kurosawa (1997, 856 votos), que era o pedido.
// Pegar o primeiro com o ano batendo escolhia o documentario.
//
// E comparar titulo exato NAO resolveria: o titulo original do filme certo
// esta em japones. O que separa os dois e a popularidade. Dai a pontuacao:
// ano e titulo entram, mas votos desempatam, e e o desempate que decide.
function pontuar(r, pedido) {
  const alvo = normalizar(pedido.originalTitle);
  const ano = Number(String(r.release_date || '').slice(0, 4)) || null;
  const distancia = (pedido.year && ano) ? Math.abs(ano - pedido.year) : 99;
  const exato = normalizar(r.original_title) === alvo || normalizar(r.title) === alvo;

  let nota = 0;
  if (exato) nota += 60;
  if (distancia === 0) nota += 40;
  else if (distancia <= 1) nota += 20;
  else if (distancia > 3) nota -= 40;
  nota += Math.min(Number(r.popularity) || 0, 20) * 2;
  nota += Math.min(Number(r.vote_count) || 0, 5000) / 250;
  return { r: r, nota: nota, exato: exato, distancia: distancia };
}

const saida = [];
for (let i = 0; i < pedidos.length; i++) {
  const pedido = pedidos[i].json;
  const corpo = (respostas[i] && respostas[i].json) || {};
  const resultados = Array.isArray(corpo.results) ? corpo.results : [];
  if (!resultados.length) continue;

  const melhor = resultados
    .map(function (r) { return pontuar(r, pedido); })
    .sort(function (a, b) { return b.nota - a.nota; })[0];

  // Sem titulo exato E sem ano proximo, e outro filme. Buraco assumido e
  // melhor que card errado — a interface conta quantos foram descartados.
  if (!melhor.exato && melhor.distancia > 1) continue;

  saida.push({ json: Object.assign({}, pedido, { tmdbId: melhor.r.id }) });
}
if (!saida.length) {
  throw new Error('Nenhum titulo do agente foi confirmado no TMDB.');
}
return saida;

// Apresentacao, e so isso. Recebe linhas da tabela movies — do upsert no
// caminho vivo, ou do SELECT num acerto de cache — e monta as URLs. Um unico
// lugar decide como um filme vira JSON, para os dois caminhos.
const IMG = 'https://image.tmdb.org/t/p/';
const entrada = $('Validar entrada').first().json;
const l1 = $('Cache L1').all();
const doCache = l1.length > 0 && l1[0].json
  && Array.isArray(l1[0].json.picks) && l1[0].json.picks.length > 0;

// Espelha src/lib/sanitize.ts. O texto autoral e a unica superficie de
// injecao que sobra, porque e a unica coisa do modelo que e renderizada.
const PROIBIDO = /https?:\/\/|www\.|<[a-z\/]|\[[^\]]*\]\([^)]*\)|javascript:|data:/i;
const INVISIVEL = /[​-‍﻿⁠]/g;
function limpar(t, max) {
  const s = String(t == null ? '' : t).replace(INVISIVEL, '').trim();
  if (!s || PROIBIDO.test(s)) return null;
  return s.slice(0, max);
}

let picks, colecao, naoAchados;
if (doCache) {
  picks = l1[0].json.picks;
  colecao = l1[0].json.collection_title;
  naoAchados = l1[0].json.not_found || [];
} else {
  const casados = $('Escolher correspondencia').all().map(function (i) { return i.json; });
  const pedidos = $('Enfileirar titulos').all().map(function (i) { return i.json; });
  picks = casados.map(function (c) {
    return { tmdb_id: c.tmdbId, reason: c.reason, rank: c.rank };
  });
  // notFound e so o que o TMDB nao confirmou — calculado antes de qualquer
  // corte. Os excedentes do limit+2 sao folga, nao descarte.
  const conf = {};
  casados.forEach(function (c) { conf[c.rank] = true; });
  naoAchados = pedidos
    .filter(function (p) { return !conf[p.rank]; })
    .map(function (p) { return limpar(p.title, 120) || 'titulo invalido'; });
  colecao = (($('Curador').first().json || {}).output || {}).collectionTitle;
}

const fatos = {};
$input.all().forEach(function (i) {
  const j = i.json;
  if (j && j.tmdb_id != null) fatos[j.tmdb_id] = j;
});

function url(base, caminho) { return caminho ? IMG + base + caminho : null; }
function num(v) { return v == null ? null : Number(v); }

// NUMERIC volta como string do no Postgres (largeNumbersOutput = text por
// padrao). Sem o Number(), rating viraria "8.3" e a UI compararia string.
function montar(d, reason) {
  return {
    tmdbId: d.tmdb_id,
    tmdbUrl: 'https://www.themoviedb.org/movie/' + d.tmdb_id,
    imdbId: d.imdb_id || null,
    title: d.title,
    originalTitle: d.original_title || null,
    year: num(d.release_year),
    tagline: d.tagline || null,
    overview: d.overview || null,
    posterUrl: url('w500', d.poster_path),
    backdropUrl: url('w1280', d.backdrop_path),
    logoUrl: url('w300', d.logo_path),
    trailerKey: d.trailer_key || null,
    rating: num(d.rating),
    voteCount: num(d.vote_count),
    imdbRating: num(d.imdb_rating),
    imdbVotes: num(d.imdb_votes),
    awards: d.awards || null,
    runtime: num(d.runtime),
    genres: d.genres || [],
    keywords: d.keywords || [],
    originalLanguage: d.original_language || null,
    spokenLanguages: d.spoken_languages || [],
    ageRating: d.age_rating || null,
    director: d.director || null,
    cast: (d.cast_members || []).map(function (a) {
      return { name: a.name, character: a.character || null, profileUrl: url('w185', a.profile_path) };
    }),
    crew: (d.crew_members || []).map(function (c) {
      return { name: c.name, role: c.role, profileUrl: url('w185', c.profile_path) };
    }),
    collection: d.collection_name || null,
    similar: (d.similar_movies || []).map(function (r) {
      return {
        tmdbId: r.tmdb_id, title: r.title, year: num(r.year),
        backdropUrl: url('w780', r.backdrop_path),
        posterUrl: url('w342', r.poster_path),
        director: null,
      };
    }),
    providers: (d.providers || []).map(function (p) {
      return { type: p.type, name: p.name, logoUrl: url('w92', p.logo_path) };
    }),
    // A UI mostra "disponibilidade verificada em {data}": provedor e nota
    // mudam, e datar a informacao e mais honesto que fingir que e de agora.
    fetchedAt: d.fetched_at ? new Date(d.fetched_at).toISOString() : new Date().toISOString(),
    reason: limpar(reason, 220) || 'Escolha do curador para o que voce pediu.',
  };
}

// A ordem do curador e informacao: o primeiro e o que ele defenderia
// primeiro. Nem o banco nem os nos HTTP garantem ordem.
const ordenados = picks.slice().sort(function (a, b) {
  return Number(a.rank || 0) - Number(b.rank || 0);
});
const filmes = [];
ordenados.forEach(function (p) {
  const d = fatos[p.tmdb_id];
  if (d) filmes.push(montar(d, p.reason));
});

return [{ json: {
  requestId: entrada.requestId,
  query: entrada.preferences,
  collectionTitle: limpar(colecao, 60) || 'Selecao do curador',
  cached: !!doCache,
  generatedAt: new Date().toISOString(),
  movies: filmes.slice(0, entrada.limit),
  notFound: naoAchados,
} }];

// Fatos crus, no formato EXATO da tabela movies: guarda o PATH, nunca a URL.
// Tamanho de imagem (w342, w500) e decisao de apresentacao e e montado em
// 'Montar resposta'; congelar a URL no banco significa reescrever a tabela
// inteira so para trocar de tamanho.
const casados = $('Escolher correspondencia').all().map(function (i) { return i.json; });
const fichas = $('TMDB detalhes').all().map(function (i) { return i.json; });
const notas = $input.all().map(function (i) { return i.json; });

function ausente(v) { return v == null || v === 'N/A' || v === ''; }
function numero(v) {
  if (ausente(v)) return null;
  const n = Number(String(v).replace(/,/g, ''));
  return Number.isFinite(n) ? n : null;
}

const linhas = [];
for (let i = 0; i < casados.length; i++) {
  const d = fichas[i];
  if (!d || !d.id) continue;
  const o = notas[i] || {};
  const temNota = o.Response === 'True';

  const creditos = d.credits || {};
  const equipe = Array.isArray(creditos.crew) ? creditos.crew : [];
  const elenco = Array.isArray(creditos.cast) ? creditos.cast : [];
  const diretor = equipe.find(function (c) { return c.job === 'Director'; });

  const lancamentos = (d.release_dates && d.release_dates.results) || [];
  const br = lancamentos.find(function (r) { return r.iso_3166_1 === 'BR'; });
  const cert = ((br && br.release_dates) || [])
    .map(function (r) { return r.certification; })
    .find(function (c) { return c; });

  const videos = (d.videos && d.videos.results) || [];
  const trailer = videos.find(function (v) { return v.site === 'YouTube' && v.type === 'Trailer'; })
    || videos.find(function (v) { return v.site === 'YouTube'; });

  const logos = (d.images && d.images.logos) || [];
  const logo = logos.find(function (l) { return l.iso_639_1 === 'pt'; }) || logos[0];

  const onde = ((d['watch/providers'] || {}).results || {}).BR || {};
  const provedores = [];
  // Os tipos ESPELHAM ProviderType em src/lib/types.ts. Gravar em portugues
  // aqui quebra todo filtro escrito contra o contrato — e quebra em SILENCIO,
  // porque o campo existe, so nunca casa. 'free' e 'ads' entram porque filme
  // gratuito com anuncio tambem e uma resposta valida para 'onde assistir'.
  ['flatrate', 'free', 'ads', 'rent', 'buy'].forEach(function (tipo) {
    (onde[tipo] || []).forEach(function (p) {
      provedores.push({ type: tipo, name: p.provider_name, logo_path: p.logo_path || null });
    });
  });

  linhas.push({
    tmdb_id: d.id,
    imdb_id: (d.external_ids && d.external_ids.imdb_id) || null,
    title: d.title || casados[i].title,
    original_title: d.original_title || null,
    release_year: d.release_date ? Number(d.release_date.slice(0, 4)) : null,
    tagline: d.tagline || null,
    overview: d.overview || null,
    poster_path: d.poster_path || null,
    backdrop_path: d.backdrop_path || null,
    logo_path: (logo && logo.file_path) || null,
    rating: typeof d.vote_average === 'number' ? Number(d.vote_average.toFixed(1)) : null,
    vote_count: d.vote_count == null ? null : d.vote_count,
    imdb_rating: temNota ? numero(o.imdbRating) : null,
    imdb_votes: temNota ? numero(o.imdbVotes) : null,
    awards: temNota && !ausente(o.Awards) ? o.Awards : null,
    runtime: d.runtime || null,
    genres: (d.genres || []).map(function (g) { return g.name; }),
    keywords: (((d.keywords || {}).keywords) || []).slice(0, 12).map(function (k) { return k.name; }),
    original_language: d.original_language || null,
    spoken_languages: (d.spoken_languages || []).map(function (l) { return l.name; }),
    age_rating: cert || null,
    director: (diretor && diretor.name) || null,
    cast_members: elenco.slice(0, 10).map(function (a) {
      return { name: a.name, character: a.character || null, profile_path: a.profile_path || null };
    }),
    crew_members: equipe.filter(function (c) {
      return ['Director', 'Screenplay', 'Writer', 'Director of Photography', 'Original Music Composer'].indexOf(c.job) !== -1;
    }).slice(0, 8).map(function (c) {
      return { name: c.name, role: c.job, profile_path: c.profile_path || null };
    }),
    collection_name: (d.belongs_to_collection && d.belongs_to_collection.name) || null,
    similar_movies: (((d.recommendations || {}).results) || []).slice(0, 8).map(function (r) {
      return {
        tmdb_id: r.id, title: r.title,
        year: r.release_date ? Number(r.release_date.slice(0, 4)) : null,
        poster_path: r.poster_path || null, backdrop_path: r.backdrop_path || null,
      };
    }),
    providers: provedores,
    trailer_key: (trailer && trailer.key) || null,
  });
}
if (!linhas.length) throw new Error('Nenhum filme sobreviveu ao enriquecimento.');

// Um unico item com o array dentro: o no Postgres roda a query uma vez so,
// com um parametro jsonb, em vez de uma query por filme.
return [{ json: { linhas: linhas } }];

const entrada = $('Validar entrada').first().json;
const resp = $('Montar resposta').first().json;
const l1 = $('Cache L1').all();
const doCache = l1.length > 0 && l1[0].json && Array.isArray(l1[0].json.picks) && l1[0].json.picks.length > 0;

let picks;
if (doCache) {
  picks = l1[0].json.picks;
} else {
  picks = $('Escolher correspondencia').all().map(function (i) {
    return { tmdb_id: i.json.tmdbId, reason: i.json.reason, rank: i.json.rank };
  });
}

// searches.request_id e uuid NOT NULL. O BFF sempre manda um; chamada de
// teste feita na mao, nao. Marcar com o uuid nulo e mais honesto que
// derrubar a gravacao de telemetria por causa de um curl.
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const requestId = UUID.test(entrada.requestId || '')
  ? entrada.requestId
  : '00000000-0000-0000-0000-000000000000';

return [{ json: {
  queryHash: $('Hash').first().json.queryHash,
  queryText: entrada.preferences,
  queryNorm: entrada.queryNorm,
  limitN: entrada.limit,
  promptVersion: entrada.promptVersion,
  picks: picks,
  notFound: resp.notFound || [],
  collectionTitle: resp.collectionTitle,
  modelUsed: doCache ? null : 'gemini',
  cacheHit: !!doCache,
  movieCount: (resp.movies || []).length,
  notFoundCount: (resp.notFound || []).length,
  latencyMs: Date.now() - Number(entrada.inicio || Date.now()),
  requestId: requestId,
} }];
